<template>
  <div class="evaluation-page">
    <header class="page-head">
      <div><span class="eyebrow">PEMBELAJARAN SANTRI</span><h1>Evaluasi & Ranking</h1><p>Pantau hasil latihan, progres belajar, dan pencapaian seluruh santri.</p></div>
      <q-btn unelevated no-caps icon="play_arrow" label="Mulai Evaluasi" class="primary" @click="startQuiz" />
    </header>

    <section class="metrics">
      <article v-for="metric in metrics" :key="metric.label">
        <div class="metric-icon" :class="metric.tone"><q-icon :name="metric.icon" size="23px" /></div>
        <div><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small></div>
      </article>
    </section>

    <section class="overview">
      <q-card flat class="panel progress-card">
        <div class="panel-head"><div><span>RINGKASAN</span><h2>Progres evaluasi</h2></div><q-select v-model="period" dense outlined :options="periods" emit-value map-options /></div>
        <div class="chart-area">
          <div class="score-ring" :style="{ '--score': average * 3.6 + 'deg' }"><div><b>{{ average }}</b><span>rata-rata</span></div></div>
          <div class="chart-copy"><strong>+8%</strong><small>dari periode sebelumnya</small><p><i></i> Nilai rata-rata <b>{{ average }}/100</b></p><p class="amber"><i></i> Tingkat kelulusan <b>{{ passRate }}%</b></p></div>
        </div>
      </q-card>

      <q-card flat class="panel ranking-card">
        <div class="panel-head"><div><span>TOP SANTRI</span><h2>Papan peringkat</h2></div><q-icon name="emoji_events" color="amber-7" size="25px" /></div>
        <div v-for="(student, index) in leaderboard.slice(0,5)" :key="student.id" class="rank-row">
          <div class="rank" :class="`top-${index + 1}`">{{ index + 1 }}</div><div class="avatar">{{ initials(student.name) }}</div>
          <div class="student"><b>{{ student.name }}</b><span>{{ student.completed }} evaluasi selesai</span></div><div class="points"><b>{{ student.score }}</b><span>poin</span></div>
        </div>
        <q-btn flat no-caps label="Lihat semua peringkat" icon-right="arrow_forward" class="view-all" @click="rankingOpen = true" />
      </q-card>
    </section>

    <q-card flat class="panel attempt-card">
      <div class="panel-head table-head"><div><span>AKTIVITAS TERBARU</span><h2>Attempt & jawaban</h2></div><q-input v-model="search" dense outlined clearable placeholder="Cari santri atau evaluasi…"><template #prepend><q-icon name="search" /></template></q-input></div>
      <q-table flat :rows="filteredAttempts" :columns="columns" row-key="id" :pagination="{ rowsPerPage: 6 }">
        <template #body-cell-student="p"><q-td :props="p"><div class="student-cell"><div class="avatar small">{{ initials(p.row.student) }}</div><div><b>{{ p.row.student }}</b><span>{{ p.row.majelis }}</span></div></div></q-td></template>
        <template #body-cell-score="p"><q-td :props="p"><b class="result" :class="tone(p.row.score)">{{ p.row.score }}</b></q-td></template>
        <template #body-cell-answers="p"><q-td :props="p"><div class="answer-cell"><q-linear-progress rounded size="7px" :value="p.row.correct/p.row.total" color="positive" track-color="green-1" /><span>{{ p.row.correct }}/{{ p.row.total }} benar</span></div></q-td></template>
        <template #body-cell-status="p"><q-td :props="p"><q-badge rounded :class="p.row.score >= 70 ? 'passed' : 'retry'">{{ p.row.score >= 70 ? 'Lulus' : 'Perlu ulang' }}</q-badge></q-td></template>
        <template #body-cell-action="p"><q-td :props="p"><q-btn flat round dense icon="visibility" @click="showDetail(p.row)" /></q-td></template>
      </q-table>
    </q-card>

    <q-dialog v-model="quizOpen"><q-card class="dialog-card"><q-card-section class="dialog-head"><div><span>EVALUASI PILIHAN GANDA</span><h2>{{ quiz.title }}</h2></div><q-btn flat round dense icon="close" v-close-popup /></q-card-section><q-card-section class="quiz-body"><div class="quiz-meta"><span>Soal {{ questionIndex+1 }} dari {{ quiz.questions.length }}</span><span>{{ answered }} terjawab</span></div><q-linear-progress rounded size="7px" :value="(questionIndex+1)/quiz.questions.length" color="positive" /><h3>{{ currentQuestion.text }}</h3><q-option-group v-model="answers[currentQuestion.id]" :options="currentQuestion.options" color="positive" type="radio" class="choices" /></q-card-section><q-card-actions align="between"><q-btn flat no-caps icon="arrow_back" label="Sebelumnya" :disable="questionIndex===0" @click="questionIndex--"/><q-btn unelevated no-caps color="positive" :label="questionIndex === quiz.questions.length-1 ? 'Selesaikan' : 'Berikutnya'" icon-right="arrow_forward" @click="next" /></q-card-actions></q-card></q-dialog>

    <q-dialog v-model="detailOpen"><q-card class="dialog-card"><q-card-section class="dialog-head"><div><span>RINCIAN ATTEMPT</span><h2>{{ selected?.student }}</h2></div><q-btn flat round dense icon="close" v-close-popup /></q-card-section><q-card-section><div class="summary"><b :class="tone(selected?.score)">{{ selected?.score }}</b><div><strong>{{ selected?.quiz }}</strong><span>{{ selected?.correct }} dari {{ selected?.total }} jawaban benar</span></div></div><q-list separator><q-item v-for="(item,i) in selected?.answers || []" :key="i"><q-item-section avatar><q-icon :name="item.correct?'check_circle':'cancel'" :color="item.correct?'positive':'negative'" /></q-item-section><q-item-section><q-item-label>{{ item.question }}</q-item-label><q-item-label caption>Jawaban: {{ item.answer }}</q-item-label></q-item-section></q-item></q-list><p v-if="!selected?.answers?.length" class="empty">Rincian jawaban belum tersedia untuk attempt ini.</p></q-card-section></q-card></q-dialog>

    <q-dialog v-model="rankingOpen"><q-card class="dialog-card"><q-card-section class="dialog-head"><div><span>PERINGKAT KESELURUHAN</span><h2>Papan peringkat santri</h2></div><q-btn flat round dense icon="close" v-close-popup /></q-card-section><q-list separator><q-item v-for="(s,i) in leaderboard" :key="s.id"><q-item-section avatar><div class="rank" :class="`top-${i+1}`">{{ i+1 }}</div></q-item-section><q-item-section><q-item-label class="text-weight-bold">{{ s.name }}</q-item-label><q-item-label caption>{{ s.completed }} evaluasi selesai</q-item-label></q-item-section><q-item-section side><b class="green-text">{{ s.score }} poin</b></q-item-section></q-item></q-list></q-card></q-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { supabase } from '../lib/supabase'

const props = defineProps({ profile: { type:Object, required:true } }), $q = useQuasar()
const period=ref('month'), search=ref(''), quizOpen=ref(false), detailOpen=ref(false), rankingOpen=ref(false), questionIndex=ref(0), selected=ref(null), answers=reactive({})
const periods=[{label:'Bulan ini',value:'month'},{label:'3 bulan',value:'quarter'},{label:'Tahun ini',value:'year'}]
const attempts=ref([
  {id:1,student:'Ahmad Fauzan',majelis:'TPQ Al-Ikhlas',quiz:'Adab Membaca Al-Qur’an',score:96,correct:24,total:25,date:'24 Sep 2026',answers:[{question:'Apa yang dibaca sebelum tilawah?',answer:'Ta’awudz',correct:true},{question:'Bagaimana posisi mushaf?',answer:'Di tempat bersih dan layak',correct:true}]},
  {id:2,student:'Siti Aisyah',majelis:'TPQ Al-Ikhlas',quiz:'Tajwid Dasar',score:92,correct:23,total:25,date:'23 Sep 2026'},
  {id:3,student:'Muhammad Rizki',majelis:'Majelis An-Nur',quiz:'Hafalan Juz 30',score:84,correct:21,total:25,date:'22 Sep 2026'},
  {id:4,student:'Nabila Putri',majelis:'TPQ Al-Ikhlas',quiz:'Tajwid Dasar',score:68,correct:17,total:25,date:'21 Sep 2026'},
  {id:5,student:'Fatih Ramadhan',majelis:'Majelis An-Nur',quiz:'Adab Membaca Al-Qur’an',score:80,correct:20,total:25,date:'20 Sep 2026'}])
const leaderboard=ref([{id:1,name:'Ahmad Fauzan',completed:12,score:1240},{id:2,name:'Siti Aisyah',completed:11,score:1185},{id:3,name:'Muhammad Rizki',completed:10,score:1090},{id:4,name:'Fatih Ramadhan',completed:9,score:975},{id:5,name:'Nabila Putri',completed:9,score:910},{id:6,name:'Zahra Kamila',completed:8,score:875}])
const quiz={title:'Adab Membaca Al-Qur’an',questions:[{id:'q1',text:'Bacaan yang dianjurkan sebelum mulai membaca Al-Qur’an adalah…',options:[{label:'Ta’awudz',value:'a',correct:true},{label:'Takbir',value:'b'},{label:'Tahmid',value:'c'},{label:'Tasbih',value:'d'}]},{id:'q2',text:'Sikap yang tepat ketika mendengar ayat Al-Qur’an dibacakan adalah…',options:[{label:'Tetap berbicara',value:'a'},{label:'Mendengarkan dengan saksama',value:'b',correct:true},{label:'Meninggalkan tempat',value:'c'},{label:'Mengeraskan suara',value:'d'}]},{id:'q3',text:'Tempat yang tepat untuk meletakkan mushaf adalah…',options:[{label:'Di lantai',value:'a'},{label:'Di bawah benda lain',value:'b'},{label:'Di tempat bersih dan layak',value:'c',correct:true},{label:'Di sembarang tempat',value:'d'}]}]}
const columns=[{name:'student',label:'Santri',field:'student',align:'left',sortable:true},{name:'quiz',label:'Evaluasi',field:'quiz',align:'left',sortable:true},{name:'score',label:'Nilai',field:'score',align:'center',sortable:true},{name:'answers',label:'Jawaban',field:'correct',align:'left'},{name:'date',label:'Tanggal',field:'date',align:'left'},{name:'status',label:'Status',field:'status',align:'center'},{name:'action',label:'',field:'action'}]
const average=computed(()=>attempts.value.length?Math.round(attempts.value.reduce((s,r)=>s+r.score,0)/attempts.value.length):0)
const passRate=computed(()=>attempts.value.length?Math.round(attempts.value.filter(r=>r.score>=70).length/attempts.value.length*100):0)
const metrics=computed(()=>[{label:'Total evaluasi',value:18,note:'4 masih aktif',icon:'quiz',tone:'green'},{label:'Attempt selesai',value:attempts.value.length,note:'Bulan ini',icon:'task_alt',tone:'blue'},{label:'Rata-rata nilai',value:average.value,note:'Dari 100 poin',icon:'monitoring',tone:'amber'},{label:'Tingkat kelulusan',value:`${passRate.value}%`,note:'Target 75%',icon:'military_tech',tone:'purple'}])
const filteredAttempts=computed(()=>{const q=(search.value||'').toLowerCase();return attempts.value.filter(r=>`${r.student} ${r.quiz} ${r.majelis}`.toLowerCase().includes(q))})
const currentQuestion=computed(()=>quiz.questions[questionIndex.value]), answered=computed(()=>Object.keys(answers).length)
const initials=(name='')=>name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase(), tone=(score=0)=>score>=85?'excellent':score>=70?'good':'low'
function startQuiz(){questionIndex.value=0;Object.keys(answers).forEach(k=>delete answers[k]);quizOpen.value=true}
function next(){if(!answers[currentQuestion.value.id])return $q.notify({type:'warning',message:'Pilih salah satu jawaban terlebih dahulu.'});if(questionIndex.value<quiz.questions.length-1)questionIndex.value++;else finish()}
function finish(){const correct=quiz.questions.filter(q=>q.options.find(o=>o.value===answers[q.id])?.correct).length,score=Math.round(correct/quiz.questions.length*100);attempts.value.unshift({id:Date.now(),student:props.profile.full_name||'Pengguna',majelis:'Evaluasi mandiri',quiz:quiz.title,score,correct,total:quiz.questions.length,date:new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(new Date()),answers:quiz.questions.map(q=>{const o=q.options.find(x=>x.value===answers[q.id]);return{question:q.text,answer:o?.label,correct:o?.correct}})});quizOpen.value=false;$q.notify({type:score>=70?'positive':'warning',message:`Evaluasi selesai. Nilai Anda ${score}.`})}
function showDetail(row){selected.value=row;detailOpen.value=true}
async function load(){if(!supabase||!props.profile.masjid_id)return;const {data,error}=await supabase.from('evaluation_attempts').select('id,score,correct_answers,total_questions,completed_at,evaluations(title),anggota(name,majelis(name))').eq('masjid_id',props.profile.masjid_id).order('completed_at',{ascending:false}).limit(50);if(!error&&data?.length)attempts.value=data.map(r=>({id:r.id,student:r.anggota?.name||'Santri',majelis:r.anggota?.majelis?.name||'–',quiz:r.evaluations?.title||'Evaluasi',score:r.score,correct:r.correct_answers,total:r.total_questions,date:new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(new Date(r.completed_at))}))}
onMounted(load)
</script>

<style scoped>
.evaluation-page{max-width:1400px;margin:auto;color:#29453d}.page-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.eyebrow,.panel-head span,.dialog-head span{color:#168066;font-size:8px;font-weight:800;letter-spacing:1.6px}.page-head h1{margin:5px 0 4px;font:600 27px Georgia,serif}.page-head p{margin:0;color:#8a9893;font-size:11px}.primary{height:42px;border-radius:10px;color:#fff;background:#126b55;font-size:10px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:16px}.metrics article{display:flex;align-items:center;gap:13px;padding:18px;border:1px solid #e1e9e6;border-radius:13px;background:#fff}.metric-icon{width:43px;height:43px;display:grid;place-items:center;flex:none;border-radius:12px}.metric-icon.green{color:#137159;background:#e7f5ef}.metric-icon.blue{color:#3672ad;background:#ebf3fb}.metric-icon.amber{color:#ad7d27;background:#fff5dd}.metric-icon.purple{color:#7756a5;background:#f3edfb}.metrics article>div:last-child{display:flex;flex-direction:column}.metrics span{color:#84928d;font-size:9px}.metrics strong{font-size:21px}.metrics small{color:#a0aaa6;font-size:8px}.overview{display:grid;grid-template-columns:1.1fr .9fr;gap:16px;margin-bottom:16px}.panel{border:1px solid #e1e9e6;border-radius:14px;background:#fff}.progress-card,.ranking-card{padding:20px}.panel-head{display:flex;align-items:center;justify-content:space-between}.panel-head h2{margin:3px 0 0;font:600 18px Georgia,serif}.panel-head .q-select{width:130px;font-size:10px}.panel-head :deep(.q-field__control){height:36px;min-height:36px;border-radius:9px}.chart-area{display:flex;align-items:center;justify-content:center;gap:42px;padding:28px 8px 14px}.score-ring{position:relative;width:145px;height:145px;display:grid;place-items:center;border-radius:50%;background:conic-gradient(#168066 var(--score),#eaf0ed 0)}.score-ring:after{content:'';position:absolute;inset:13px;border-radius:50%;background:#fff}.score-ring div{z-index:1;display:flex;flex-direction:column;align-items:center}.score-ring b{font-size:36px}.score-ring span{color:#92a09b;font-size:9px}.chart-copy{display:flex;flex-direction:column}.chart-copy>strong{color:#168066;font-size:20px}.chart-copy>small{margin-bottom:18px;color:#96a29e;font-size:8px}.chart-copy p{display:flex;align-items:center;gap:7px;margin:5px 0;color:#74847e;font-size:9px}.chart-copy p b{margin-left:auto}.chart-copy i{width:8px;height:8px;border-radius:50%;background:#168066}.chart-copy .amber i{background:#d9a23c}.rank-row{display:flex;align-items:center;gap:10px;padding:9px 2px;border-bottom:1px solid #edf1ef}.rank{width:25px;height:25px;display:grid;place-items:center;border-radius:8px;color:#84928d;background:#f1f4f3;font-size:9px;font-weight:800}.top-1{color:#875e0f;background:#fff0bf}.top-2{color:#66716e;background:#e9eeec}.top-3{color:#8d5838;background:#f9e5d7}.avatar{width:34px;height:34px;display:grid;place-items:center;border-radius:10px;color:#fff;background:linear-gradient(145deg,#16745d,#40a88f);font-size:9px;font-weight:800}.student,.points{display:flex;flex-direction:column}.student{flex:1}.student b{font-size:10px}.student span,.points span{color:#9aa5a1;font-size:8px}.points{text-align:right}.view-all{width:100%;margin-top:8px;color:#16745d;font-size:9px}.table-head{padding:20px 20px 12px}.table-head .q-input{width:240px;font-size:10px}.student-cell{display:flex;align-items:center;gap:9px}.avatar.small{width:30px;height:30px}.student-cell>div:last-child{display:flex;flex-direction:column}.student-cell span{color:#9ca7a3;font-size:8px}.answer-cell{display:flex;align-items:center;gap:8px;min-width:130px}.answer-cell .q-linear-progress{width:70px}.answer-cell span{font-size:8px}.result{font-size:13px}.excellent,.green-text{color:#168066}.good{color:#b17b18}.low{color:#c55757}.passed,.retry{padding:5px 9px}.passed{color:#116b54;background:#e6f5ef}.retry{color:#a76822;background:#fff2dc}.dialog-card{width:min(610px,92vw);border-radius:17px}.dialog-head{display:flex;justify-content:space-between;padding:23px}.dialog-head h2{margin:4px 0 0;font:600 21px Georgia,serif}.quiz-body{padding:10px 28px 24px}.quiz-meta{display:flex;justify-content:space-between;margin-bottom:9px;color:#82908b;font-size:9px}.quiz-body h3{margin:24px 0 18px;font-size:16px;line-height:1.5}.choices :deep(.q-radio){width:100%;margin:5px 0;padding:10px;border:1px solid #e4ebe8;border-radius:10px;font-size:11px}.dialog-card .q-card__actions{padding:15px 23px;border-top:1px solid #edf1ef}.summary{display:flex;align-items:center;gap:15px;margin-bottom:15px;padding:16px;border-radius:12px;background:#f4f8f6}.summary>b{font-size:33px}.summary>div{display:flex;flex-direction:column}.summary span,.empty{color:#8a9893;font-size:10px}@media(max-width:1100px){.metrics{grid-template-columns:1fr 1fr}.overview{grid-template-columns:1fr}}@media(max-width:650px){.page-head{align-items:flex-start}.page-head p{max-width:220px}.metrics{gap:9px}.metrics article{padding:12px}.metric-icon{width:36px;height:36px}.chart-area{gap:18px}.score-ring{width:120px;height:120px}.table-head{align-items:flex-start;gap:12px;flex-direction:column}.table-head .q-input{width:100%}}
</style>
